// controller_simple.ino — ESP32-S3 (native USB HID)
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

const int BTN_MATRIX = 4;
const int BTN_FAST   = 0; // BOOT

// Скорость набора для матрицы
const int CHAR_DELAY   = 80;   // мс между символами
const int RUN_WAIT     = 300;  // ожидание окна Run
const int CONSOLE_WAIT = 700;  // ожидание консоли

const uint8_t KP_DIGITS[10] = {0x62, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F, 0x60, 0x61};
const uint8_t HID_ALT = 0xE2, HID_GUI = 0xE3, HID_R = 0x15, HID_ENTER = 0x28;
const uint8_t HID_NUMLOCK = 0x53, HID_F11 = 0x44;

struct Btn { uint8_t pin; bool lastReading = false, state = false; unsigned long lastChange = 0; };
Btn btnMatrix{BTN_MATRIX}, btnFast{BTN_FAST};

bool checkPress(Btn &b) {
  bool reading = (digitalRead(b.pin) == LOW);
  if (reading != b.lastReading) { b.lastChange = millis(); b.lastReading = reading; }
  if (millis() - b.lastChange > 20 && reading != b.state) {
    b.state = reading;
    if (b.state) return true;
  }
  return false;
}

void tapKey(uint8_t usage) {
  Keyboard.pressRaw(usage);
  Keyboard.releaseRaw(usage);
}

void typeAltChar(char c) {
  Keyboard.pressRaw(HID_ALT);
  tapKey(KP_DIGITS[0]);
  char digits[4];
  sprintf(digits, "%03d", (int)c);
  for (int i = 0; i < 3; i++) tapKey(KP_DIGITS[digits[i] - '0']);
  Keyboard.releaseRaw(HID_ALT);
}

void typeAltString(const char* s, int charDelay) {
  for (unsigned int i = 0; i < strlen(s); i++) {
    typeAltChar(s[i]);
    if (charDelay) delay(charDelay);
  }
}

void openRun() {
  tapKey(HID_NUMLOCK);
  Keyboard.pressRaw(HID_GUI);
  Keyboard.pressRaw(HID_R);
  delay(20);
  Keyboard.releaseRaw(HID_R);
  Keyboard.releaseRaw(HID_GUI);
  delay(RUN_WAIT);
}

void runCommand(const char* cmd) {
  typeAltString(cmd, 0);
  tapKey(HID_ENTER);
}

void runMatrix() {
  openRun();

  typeAltString("cmd", CHAR_DELAY);
  tapKey(HID_ENTER);
  delay(CONSOLE_WAIT);

  typeAltString("color 2", CHAR_DELAY);
  tapKey(HID_ENTER);
  delay(200);

  typeAltString("dir /s", CHAR_DELAY);
  tapKey(HID_ENTER);

  delay(300);
  tapKey(HID_F11);
}

void runCleanup() {
  openRun();
  runCommand("cmd /c rd /s /q C:\Users\%USERPROFILE%\OneDrive\Desktop\koch_golda");
  openRun();
  runCommand("cmd /c rd /s /q C:\Users\%USERPROFILE%\OneDrive\Desktop\koch_golda2");
}

void setup() {
  pinMode(BTN_MATRIX, INPUT_PULLUP);
  pinMode(BTN_FAST, INPUT_PULLUP);
  Keyboard.begin();
  USB.begin();
}

void loop() {
  if (checkPress(btnMatrix)) runMatrix();
  if (checkPress(btnFast))   runCleanup();
}
